import {
  Mjml,
  MjmlBody,
  MjmlButton,
  MjmlFont,
  MjmlHead,
  MjmlPreview,
  MjmlText,
  MjmlWrapper,
  MjmlColumn,
  MjmlImage,
  MjmlSection,
  MjmlSpacer,
} from "@faire/mjml-react";
import type { ReactNode } from "react";

import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const FeatureEmailShell = ({
  children,
  pageBackgroundColor,
  preview,
  theme,
}: {
  children: ReactNode;
  pageBackgroundColor: string;
  preview: string;
  theme: EmailTheme;
}) => (
  <Mjml>
    <MjmlHead>
      <MjmlPreview>{preview}</MjmlPreview>
      <MjmlFont href="https://rsms.me/inter/inter.css" name="Inter" />
    </MjmlHead>
    <MjmlBody
      backgroundColor={pageBackgroundColor}
      width={theme.containerWidth}
    >
      <MjmlWrapper padding="0">{children}</MjmlWrapper>
    </MjmlBody>
  </Mjml>
);

const FeatureCopy = ({
  align = "left",
  body,
  buttonHref,
  buttonLabel,
  heading,
  headingColor,
  linkColor,
  textColor,
}: {
  align?: "center" | "left" | "right";
  body: string;
  buttonHref: string;
  buttonLabel: string;
  heading: string;
  headingColor: string;
  linkColor: string;
  textColor: string;
}) => (
  <>
    {heading ? (
      <MjmlText
        align={align}
        color={headingColor}
        fontFamily={fontFamily}
        fontSize="24px"
        fontWeight="600"
        lineHeight="32px"
        padding="0"
      >
        {heading}
      </MjmlText>
    ) : null}
    <MjmlText
      align={align}
      color={textColor}
      fontFamily={fontFamily}
      fontSize="16px"
      fontWeight="300"
      lineHeight="24px"
      padding={heading ? "16px 0 0" : "0"}
    >
      {body}
    </MjmlText>
    <MjmlButton
      align={align}
      backgroundColor="transparent"
      color={linkColor}
      fontFamily={fontFamily}
      fontSize="16px"
      fontWeight="500"
      href={buttonHref}
      innerPadding="6px 0"
      padding="16px 0 0"
    >
      {buttonLabel} →
    </MjmlButton>
  </>
);

type Feature_FeatureWithMultipleProductImagesVariant =
  | "logo-left"
  | "logo-right"
  | "images-left"
  | "images-right";

interface Feature_FeatureWithMultipleProductImagesProps {
  theme?: EmailTheme;
  heading?: string;
  body?: string;
  largeImageSrc?: string;
  largeImageAlt?: string;
  middleImageSrc?: string;
  middleImageAlt?: string;
  smallImageSrc?: string;
  smallImageAlt?: string;
  logoSrc?: string;
  logoAlt?: string;
  buttonLabel?: string;
  buttonHref?: string;
  arrowIconSrc?: string;
  pageBackgroundColor?: string;
  backgroundColor?: string;
  logoBackgroundColor?: string;
  headingColor?: string;
  textColor?: string;
  linkColor?: string;
  variant?: Feature_FeatureWithMultipleProductImagesVariant;
}

const Feature_FeatureWithMultipleProductImagesSection = (
  props: Omit<Feature_FeatureWithMultipleProductImagesProps, "theme">
) => {
  const {
    backgroundColor,
    body,
    buttonHref,
    buttonLabel,
    heading,
    headingColor,
    largeImageAlt,
    largeImageSrc,
    linkColor,
    logoAlt,
    logoSrc,
    middleImageAlt,
    middleImageSrc,
    smallImageAlt,
    smallImageSrc,
    textColor,
    variant,
  } = {
    backgroundColor: "#fffffe",
    buttonHref: "https://example.com",
    buttonLabel: "Discover more",
    headingColor: "#030712",
    largeImageAlt: "Product Image 1",
    linkColor: "#4f46e5",
    logoAlt: "Visa",
    logoSrc: emailAsset("logos/logo-visa.png"),
    middleImageAlt: "Product Image 2",
    smallImageAlt: "Product Image 3",
    textColor: "#4b5563",
    variant: "logo-left",
    ...props,
  };
  const logoVariant = variant.startsWith("logo-");
  const artworkRight = variant.endsWith("-right");
  const resolved = logoVariant
    ? {
        body:
          body ??
          "Accepting cards should be quick, secure, and seamless. Discover our tools that simplify every transaction.",
        heading: heading ?? "Built for the journey ahead.",
        large: largeImageSrc ?? emailAsset("feature/feature-2-lg.jpg"),
        middle: middleImageSrc ?? emailAsset("feature/feature-2-sm.jpg"),
        small: smallImageSrc ?? emailAsset("feature/feature-2-sm.jpg"),
      }
    : {
        body:
          body ??
          "Explore durable layers that balance insulation, breathability, and all-day comfort.",
        heading: heading ?? "Outdoor essentials redefined.",
        large: largeImageSrc ?? emailAsset("feature/feature-2-lg-2.jpg"),
        middle: middleImageSrc ?? emailAsset("feature/feature-2-md.jpg"),
        small: smallImageSrc ?? emailAsset("feature/feature-2-sm-2.jpg"),
      };
  const artwork = (
    <MjmlColumn padding="0" verticalAlign="top" width="50%">
      {logoVariant ? (
        <>
          <MjmlImage
            align="center"
            alt={logoAlt}
            padding="24px"
            src={logoSrc}
            width="120px"
          />
          <MjmlSpacer height="16px" />
        </>
      ) : null}
      <MjmlImage
        alt={largeImageAlt}
        borderRadius="4px"
        padding="0"
        src={resolved.large}
        width="254px"
      />
      <MjmlSpacer height="16px" />
      <MjmlImage
        alt={middleImageAlt}
        borderRadius="4px"
        padding="0"
        src={resolved.middle}
        width="160px"
      />
      <MjmlSpacer height="12px" />
      <MjmlImage
        alt={smallImageAlt}
        borderRadius="4px"
        padding="0"
        src={resolved.small}
        width="96px"
      />
    </MjmlColumn>
  );
  const copy = (
    <MjmlColumn padding="0 0 0 32px" verticalAlign="middle" width="50%">
      <FeatureCopy
        body={resolved.body}
        buttonHref={buttonHref}
        buttonLabel={buttonLabel}
        heading={resolved.heading}
        headingColor={headingColor}
        linkColor={linkColor}
        textColor={textColor}
      />
    </MjmlColumn>
  );
  return (
    <MjmlSection backgroundColor={backgroundColor} padding="44px 24px">
      {artworkRight ? copy : artwork}
      {artworkRight ? artwork : copy}
    </MjmlSection>
  );
};

const Feature_FeatureWithMultipleProductImages = ({
  pageBackgroundColor = "#f1f5f9",
  theme = defaultTheme,
  ...props
}: Feature_FeatureWithMultipleProductImagesProps) => (
  <FeatureEmailShell
    pageBackgroundColor={pageBackgroundColor}
    preview="Built for the journey ahead"
    theme={theme}
  >
    <Feature_FeatureWithMultipleProductImagesSection {...props} />
  </FeatureEmailShell>
);

Feature_FeatureWithMultipleProductImages.PreviewProps = {
  theme: defaultTheme,
  variant: "logo-left",
} satisfies Feature_FeatureWithMultipleProductImagesProps;

const __Feature = Feature_FeatureWithMultipleProductImages;

export interface ProductImagesFeatureProps {
  theme?: Parameters<typeof __Feature>[0]["theme"];
  heading?: string;
  body?: string;
  images?: {
    src: string;
    alt?: string;
  }[];
  logo?: {
    src: string;
    alt?: string;
  };
  action?: {
    href: string;
    label: string;
    iconSrc?: string;
  };
  placement?: "left" | "right";
  presentation?: "images" | "logo";
}

const productImagesFeatureValues = ({
  action,
  images,
  logo,
}: Pick<ProductImagesFeatureProps, "action" | "images" | "logo">) => ({
  arrowIconSrc: action?.iconSrc,
  buttonHref: action?.href,
  buttonLabel: action?.label,
  largeImageAlt: images?.[0]?.alt,
  largeImageSrc: images?.[0]?.src,
  logoAlt: logo?.alt,
  logoSrc: logo?.src,
  middleImageAlt: images?.[1]?.alt,
  middleImageSrc: images?.[1]?.src,
  smallImageAlt: images?.[2]?.alt,
  smallImageSrc: images?.[2]?.src,
});

export const ProductImagesFeature = ({
  theme,
  heading,
  body,
  images,
  logo,
  action,
  placement = "right",
  presentation = "images",
}: ProductImagesFeatureProps) => {
  const values = productImagesFeatureValues({ action, images, logo });

  return (
    <__Feature
      {...values}
      body={body}
      heading={heading}
      theme={theme}
      variant={
        presentation === "logo" ? `logo-${placement}` : `images-${placement}`
      }
    />
  );
};

ProductImagesFeature.PreviewProps = {
  placement: "right",
  presentation: "images",
} satisfies ProductImagesFeatureProps;

const ASSET_ORIGIN = "https://www.emailcn.run";
const ICONS8_ORIGIN = "https://img.icons8.com";
const UNSPLASH_ORIGIN = "https://images.unsplash.com";

const portraitIds = [
  "photo-1500648767791-00dcc994a43e",
  "photo-1507003211169-0a1dd7228f2d",
  "photo-1494790108377-be9c29b29330",
  "photo-1438761681033-6461ffad8d80",
  "photo-1534528741775-53994a69daeb",
  "photo-1506794778202-cad84cf45f1c",
] as const;

const productIds = [
  "photo-1521572163474-6864f9cf17ab",
  "photo-1503341504253-dff4815485f1",
  "photo-1576566588028-4147f3842f27",
  "photo-1562157873-818bc0726f68",
] as const;

const socialIconSlugs = {
  discord: "discord-logo",
  facebook: "facebook-new",
  github: "github",
  instagram: "instagram-new",
  linkedin: "linkedin",
  slack: "slack-new",
  x: "twitterx--v1",
  youtube: "youtube-play",
} as const;

const brandIconSlugs = [
  [/(?:btc|bitcoin)/i, "bitcoin--v1"],
  [/(?:eth|ethereum)/i, "ethereum"],
  [/visa/i, "visa"],
  [/mastercard/i, "mastercard-logo"],
  [/apple-pay/i, "apple-pay"],
  [/google-pay/i, "google-pay"],
  [/klarna/i, "klarna"],
  [/stripe/i, "stripe"],
  [/fedex/i, "fedex"],
  [/north-face/i, "the-north-face"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/teams\/member-\d+-lg/i.test(path)) {
    return [800, 560] as const;
  }
  if (/teams\/member-\d+/i.test(path)) {
    return [600, 600] as const;
  }
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

const getIndexedAsset = (path: string, assets: readonly string[]) => {
  const explicitIndex = path.match(
    /(?:member|avatar|product-list|shopping-cart)-(\d+)/i
  )?.[1];
  const index = explicitIndex
    ? Number.parseInt(explicitIndex, 10) - 1
    : hashString(path);

  return assets[((index % assets.length) + assets.length) % assets.length];
};

const getUnsplashAsset = (id: string, width: number, height: number) =>
  `${UNSPLASH_ORIGIN}/${id}?auto=format&fit=crop&w=${width}&h=${height}&q=80`;

const getIcons8Asset = (
  slug: string,
  {
    color,
    style = "ios-filled",
  }: {
    color?: string;
    style?: "color" | "ios" | "ios-filled";
  } = {}
) =>
  color
    ? `${ICONS8_ORIGIN}/${style}/50/${color}/${slug}.png`
    : `${ICONS8_ORIGIN}/${style}/50/${slug}.png`;

const getStoreBadgeAsset = (path: string) => {
  if (/badge-app-store/i.test(path)) {
    return "https://developer.apple.com/assets/elements/badges/download-on-the-app-store.svg";
  }
  if (/badge-google-play/i.test(path)) {
    return "https://play.google.com/intl/en_us/badges/static/images/badges/en_badge_web_generic.png";
  }
};

const getSocialIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  for (const [name, slug] of Object.entries(socialIconSlugs)) {
    if (new RegExp(`(?:^|[-/])${name}(?:[-.]|$)`, "i").test(path)) {
      return getIcons8Asset(slug, { color: foreground });
    }
  }
};

const getUtilityIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  if (/star-half/i.test(path)) {
    return getIcons8Asset("star-half-empty", { color: "374151" });
  }
  if (/star-solid/i.test(path)) {
    return getIcons8Asset("star--v1", { color: "374151" });
  }
  if (/edit/i.test(path)) {
    return getIcons8Asset("edit--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/arrow-right/i.test(path)) {
    return getIcons8Asset("long-arrow-right--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/chevron-right/i.test(path)) {
    return getIcons8Asset("chevron-right", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/check/i.test(path)) {
    return getIcons8Asset("checkmark--v1", { color: foreground });
  }
};

const getBrandIconAsset = (path: string) => {
  const match = brandIconSlugs.find(([pattern]) => pattern.test(path));

  return match
    ? getIcons8Asset(match[1], {
        style: "color",
      })
    : undefined;
};

const getWordmarkAsset = (path: string) => {
  const isLight = /light/i.test(path);
  const background = isLight ? "030712" : "FFFFFF";
  const foreground = isLight ? "FFFFFF" : "111827";

  return `https://placehold.co/320x96/${background}/${foreground}.png?text=EMAILCN`;
};

const getIconAsset = (path: string) =>
  getStoreBadgeAsset(path) ??
  getSocialIconAsset(path) ??
  getUtilityIconAsset(path) ??
  getBrandIconAsset(path);

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const iconAsset = getIconAsset(normalizedPath);
  if (iconAsset) {
    return iconAsset;
  }

  const seed = getSeed(normalizedPath);
  const [width, height] = getDimensions(normalizedPath);

  if (/teams\/hero/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1521737711867-e3b97375f902", width, height);
  }

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, portraitIds),
      width,
      height
    );
  }

  if (/products\/shoe/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1542291026-7eec264c27ff", width, height);
  }

  if (/products\/phone/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1511707171634-5f897ff02aa9", width, height);
  }

  if (
    /(?:product-detail|product-lists|products\/product|shopping-cart)/i.test(
      normalizedPath
    )
  ) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, productIds),
      width,
      height
    );
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (/(?:emailcn|maizzle|logo|insignia)/i.test(normalizedPath)) {
    return getWordmarkAsset(normalizedPath);
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
